import java.util.*;

class Staff {
    private static final Comparator<Employee> BY_PAY =
        Comparator.comparingInt(Employee::salary).reversed().thenComparing(Employee::name);

    static List<Employee> bySalary(List<Employee> staff) {
        List<Employee> copy = new ArrayList<>(staff);
        copy.sort(BY_PAY);
        return copy;
    }

    static List<Employee> byDeptThenAge(List<Employee> staff) {
        List<Employee> copy = new ArrayList<>(staff);
        copy.sort(Comparator.comparing(Employee::dept).thenComparingInt(Employee::age).thenComparing(Employee::name));
        return copy;
    }

    static Map<String, Employee> oldestPerDept(List<Employee> staff) {
        Comparator<Employee> older = Comparator.comparingInt(Employee::age).thenComparing(Employee::name, Comparator.reverseOrder());
        Map<String, Employee> result = new TreeMap<>();
        for (Employee e : staff) {
            Employee current = result.get(e.dept());
            if (current == null || older.compare(e, current) > 0) result.put(e.dept(), e);
        }
        return result;
    }

    static List<String> topEarners(List<Employee> staff, int n) {
        List<String> names = new ArrayList<>();
        for (Employee e : bySalary(staff)) {
            if (names.size() == n) break;
            names.add(e.name());
        }
        return names;
    }
}

unitTests:
List<Employee> staff = List.of(
    new Employee("Grace", "eng", 9000, 45),
    new Employee("Ada", "eng", 9000, 36),
    new Employee("Linus", "ops", 7000, 30),
    new Employee("Ken", "ops", 7500, 52),
    new Employee("Barbara", "eng", 8000, 52),
    new Employee("Alan", "ops", 6000, 52));

test("by salary", () -> {
    checkEq(Staff.bySalary(staff).stream().map(Employee::name).toList(), List.of("Ada", "Grace", "Barbara", "Ken", "Linus", "Alan"));
    checkEq(staff.get(0).name(), "Grace");
});

test("by department then age", () -> {
    checkEq(Staff.byDeptThenAge(staff).stream().map(Employee::name).toList(), List.of("Ada", "Grace", "Barbara", "Linus", "Alan", "Ken"));
});

test("oldest per department", () -> {
    Map<String, Employee> oldest = Staff.oldestPerDept(staff);
    checkEq(new ArrayList<>(oldest.keySet()), List.of("eng", "ops"));
    checkEq(oldest.get("eng").name(), "Barbara");
    checkEq(oldest.get("ops").name(), "Alan");
});

test("top earners", () -> {
    checkEq(Staff.topEarners(staff, 3), List.of("Ada", "Grace", "Barbara"));
    checkEq(Staff.topEarners(staff, 0), List.of());
    checkEq(Staff.topEarners(List.of(), 2), List.of());
});

